/**
 * Filter spaces by query (matches spaceNumber, room name, or unit)
 */
export function searchPlanonSpaces(query: string, limit = 50): PlanonSpaceItem[] {
  if (!query.trim()) return PLANON_SPACES_DATA.slice(0, limit);
  const q = query.toLowerCase().trim();
  return PLANON_SPACES_DATA.filter(
    (s) =>
      s.spaceNumber.toLowerCase().includes(q) ||
      s.name.toLowerCase().includes(q) ||
      s.code.toLowerCase().includes(q) ||
      s.building.toLowerCase().includes(q) ||
      s.unit.toLowerCase().includes(q)
  ).slice(0, limit);
}

/**
 * Filter spaces strictly by selected property (building or cluster) and optional space query
 */
export function getSpacesForProperty(selectedProperty: string, query = '', limit = 50): PlanonSpaceItem[] {
  const p = selectedProperty.trim().toLowerCase();
  const q = query.trim().toLowerCase();

  let propertySpaces: PlanonSpaceItem[] = PLANON_SPACES_DATA;

  if (p) {
    // 1. Direct prefix match against spaceNumber (e.g. "TBCV1-H-H01" -> matches "TBCV1-H-H01-001")
    const prefixMatched = PLANON_SPACES_DATA.filter((s) =>
      s.spaceNumber.toLowerCase().startsWith(p) || s.spaceNumber.toLowerCase().startsWith(`${p}-`)
    );

    if (prefixMatched.length > 0) {
      propertySpaces = prefixMatched;
    } else {
      // 2. Check building code match (e.g. "H01", "C10", "D04")
      const bldMatched = PLANON_SPACES_DATA.filter((s) => s.building.toLowerCase() === p);
      if (bldMatched.length > 0) {
        propertySpaces = bldMatched;
      } else {
        // 3. Substring match against spaceNumber or building
        const substrMatched = PLANON_SPACES_DATA.filter(
          (s) =>
            s.spaceNumber.toLowerCase().includes(p) ||
            s.building.toLowerCase().includes(p) ||
            s.code.toLowerCase().includes(p)
        );
        if (substrMatched.length > 0) {
          propertySpaces = substrMatched;
        }
      }
    }
  }

  if (q) {
    return propertySpaces
      .filter(
        (s) =>
          s.spaceNumber.toLowerCase().includes(q) ||
          s.name.toLowerCase().includes(q) ||
          s.unit.toLowerCase().includes(q) ||
          s.building.toLowerCase().includes(q)
      )
      .slice(0, limit);
  }

  return propertySpaces.slice(0, limit);
}

/**
 * Filter location codes by query
 */
export function searchPlanonLocations(query: string, limit = 50): string[] {
  if (!query.trim()) return PLANON_LOCATION_CODES.slice(0, limit);
  const q = query.toLowerCase().trim();
  return PLANON_LOCATION_CODES.filter((code) => code.toLowerCase().includes(q)).slice(0, limit);
}
